337	        Validate.notEmpty(tag);
338	        Validate.notNull(attributes);
339	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
340	
341	        TagName tagName = TagName.valueOf(tag);
342	        Set<AttributeKey> attributeSet = new HashSet<>();
343	        for (String key : attributes) {
344	            Validate.notEmpty(key);
345	            attributeSet.add(AttributeKey.valueOf(key));
346	        }
347	        if(tagNames.contains(tagName) && this.attributes.containsKey(tagName)) { // Only look in sub-maps if tag was allowed
348	            Set<AttributeKey> currentSet = this.attributes.get(tagName);
349	            currentSet.removeAll(attributeSet);
350	
351	            if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
352	                this.attributes.remove(tagName);
353	        }
354	        if(tag.equals(All)) { // Attribute needs to be removed from all individually set tags
355	            Iterator<Map.Entry<TagName, Set<AttributeKey>>> it = this.attributes.entrySet().iterator();
356	            while (it.hasNext()) {
357	                Map.Entry<TagName, Set<AttributeKey>> entry = it.next();
358	                Set<AttributeKey> currentSet = entry.getValue();
359	                currentSet.removeAll(attributeSet);
360	                if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
