374	
375	     @param tag   The tag the enforced attribute is for. The tag will be added to the allowed tag list if necessary.
376	     @param attribute   The attribute name
377	     @param value The enforced attribute value
378	     @return this (for chaining)
379	     */
380	    public Safelist addEnforcedAttribute(String tag, String attribute, String value) {
381	        Validate.notEmpty(tag);
382	        Validate.notEmpty(attribute);
383	        Validate.notEmpty(value);
384	
385	        TagName tagName = TagName.valueOf(tag);
386	        tagNames.add(tagName);
387	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
388	        AttributeValue attrVal = AttributeValue.valueOf(value);
389	
390	        Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.computeIfAbsent(tagName, k -> new HashMap<>());
391	        attrMap.put(attrKey, attrVal);
392	        return this;
393	    }
