418	    /**
419	     * Configure this Safelist to preserve relative links in an element's URL attribute, or convert them to absolute
420	     * links. By default, this is <b>false</b>: URLs will be  made absolute (e.g. start with an allowed protocol, like
421	     * e.g. {@code http://}.
422	     *
423	     * @param preserve {@code true} to allow relative links, {@code false} (default) to deny
424	     * @return this Safelist, for chaining.
425	     * @see #addProtocols
426	     */
427	    public Safelist preserveRelativeLinks(boolean preserve) {
428	        preserveRelativeLinks = preserve;
429	        return this;
430	    }
431	
432	    /**
433	     * Get the current setting for preserving relative links.
434	     * @return {@code true} if relative links are preserved, {@code false} if they are converted to absolute.
435	     */
436	    public boolean preserveRelativeLinks() {
437	        return preserveRelativeLinks;
438	    }
439	
440	    /**
441	     Add allowed URL protocols for an element's URL attribute. This restricts the possible values of the attribute to
442	     URLs with the defined protocol.
443	     <p>
444	     E.g.: <code>addProtocols("a", "href", "ftp", "http", "https")</code>
445	     </p>
446	     <p>
447	     To allow a link to an in-page URL anchor (i.e. <code>&lt;a href="#anchor"&gt;</code>, add a <code>#</code>:<br>
448	     E.g.: <code>addProtocols("a", "href", "#")</code>
449	     </p>
450	
451	     @param tag       Tag the URL protocol is for
452	     @param attribute       Attribute name
453	     @param protocols List of valid protocols
454	     @return this, for chaining
455	     */
456	    public Safelist addProtocols(String tag, String attribute, String... protocols) {
457	        Validate.notEmpty(tag);
458	        Validate.notEmpty(attribute);
459	        Validate.notNull(protocols);
460	
461	        TagName tagName = TagName.valueOf(tag);
462	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
463	        Map<AttributeKey, Set<Protocol>> attrMap = this.protocols.computeIfAbsent(tagName, k -> new HashMap<>());
464	        Set<Protocol> protSet = attrMap.computeIfAbsent(attrKey, k -> new HashSet<>());
465	
466	        for (String protocol : protocols) {
467	            Validate.notEmpty(protocol);
468	            Protocol prot = Protocol.valueOf(protocol);
469	            protSet.add(prot);
470	        }
471	        return this;
472	    }
473	
474	    /**
475	     Remove allowed URL protocols for an element's URL attribute. If you remove all protocols for an attribute, that
476	     attribute will allow any protocol.
477	     <p>
478	     E.g.: <code>removeProtocols("a", "href", "ftp")</code>
479	     </p>
480	
481	     @param tag Tag the URL protocol is for
482	     @param attribute Attribute name
483	     @param removeProtocols List of invalid protocols
484	     @return this, for chaining
485	     */
486	    public Safelist removeProtocols(String tag, String attribute, String... removeProtocols) {
487	        Validate.notEmpty(tag);
488	        Validate.notEmpty(attribute);
489	        Validate.notNull(removeProtocols);
490	
491	        TagName tagName = TagName.valueOf(tag);
492	        AttributeKey attr = AttributeKey.valueOf(attribute);
493	
494	        // make sure that what we're removing actually exists; otherwise can open the tag to any data and that can
495	        // be surprising
496	        Validate.isTrue(protocols.containsKey(tagName), "Cannot remove a protocol that is not set.");
497	        Map<AttributeKey, Set<Protocol>> tagProtocols = protocols.get(tagName);
498	        Validate.isTrue(tagProtocols.containsKey(attr), "Cannot remove a protocol that is not set.");
499	
500	        Set<Protocol> attrProtocols = tagProtocols.get(attr);
501	        for (String protocol : removeProtocols) {
502	            Validate.notEmpty(protocol);
503	            attrProtocols.remove(Protocol.valueOf(protocol));
504	        }
505	
506	        if (attrProtocols.isEmpty()) { // Remove protocol set if empty
507	            tagProtocols.remove(attr);
508	            if (tagProtocols.isEmpty()) // Remove entry for tag if empty
509	                protocols.remove(tagName);
510	        }
511	        return this;
512	    }
513	
514	    /**
515	     * Test if the supplied tag is allowed by this safelist.
516	     * @param tag test tag
517	     * @return true if allowed
518	     */
519	    public boolean isSafeTag(String tag) {
520	        return tagNames.contains(TagName.valueOf(tag));
521	    }
522	
523	    /**
524	     * Test if the supplied attribute is allowed by this safelist for this tag.
525	     * <p>This method does not modify the input element or attribute.</p>
526	     * @param tagName tag to consider allowing the attribute in
527	     * @param el element under test, to confirm protocol
528	     * @param attr attribute under test
529	     * @return true if allowed
530	     */
531	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
532	        TagName tag = TagName.valueOf(tagName);
533	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
534	
535	        Set<AttributeKey> okSet = attributes.get(tag);
536	        if (okSet != null && okSet.contains(key)) {
537	            if (protocols.containsKey(tag)) {
538	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
539	                // ok if not defined protocol; otherwise test
540	                return !attrProts.containsKey(key) || isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key));
541	            } else { // attribute found, no protocols defined, so OK
542	                return true;
543	            }
544	        }
545	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
546	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
547	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
548	            // if the input already has that exact value, treat it as safe
549	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
550	        }
551	        // no attributes defined for tag, try :all tag
552	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
553	    }
554	
555	    private String getProtocolValue(Element el, Attribute attr) {
556	        String value = el.absUrl(attr.getKey());
557	        if (value.isEmpty() && !StringUtil.hasHttpScheme(attr.getValue()))
558	            value = attr.getValue(); // if it could not be made abs, run as-is to allow custom unknown protocols
559	        return value;
560	    }
561	
562	    /**
563	     Test if the supplied attribute is structurally allowed on this tag by the safelist, without applying the
564	     whole-value protocol check. This is used for attributes whose value is validated piece by piece by the
565	     {@link Cleaner} (currently {@code srcset}, whose individual candidate URLs are checked separately); ordinary
566	     attributes use {@link #isSafeAttribute(String, Element, Attribute)}.
567	     @param tagName tag to consider allowing the attribute in
568	     @param el element under test
569	     @param attr attribute under test
570	     @return true if the attribute is allowed by the tag/attribute configuration, regardless of its value
571	     */
572	    boolean isAllowedAttribute(String tagName, Element el, Attribute attr) {
573	        TagName tag = TagName.valueOf(tagName);
574	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
575	
576	        Set<AttributeKey> okSet = attributes.get(tag);
577	        if (okSet != null && okSet.contains(key)) return true;
578	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
579	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
580	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
581	        }
582	        return !tagName.equals(All) && isAllowedAttribute(All, el, attr);
583	    }
584	
585	    /**
586	     Get the allowed protocol set that governs the individual URLs inside a {@code srcset} attribute on the given
587	     tag. Because a {@code srcset} value carries multiple candidate URLs, each one is checked against the same
588	     protocol policy as an ordinary URI attribute: an explicit {@code srcset} policy wins, otherwise the tag's
589	     {@code src} policy applies, falling back to the {@code :all} tag in the same order.
590	     @param tagName the tag carrying the srcset attribute
591	     @return the allowed protocols (never null; an empty set means no protocol restriction applies)
592	     */
593	    Set<Protocol> srcsetProtocols(String tagName) {
594	        TagName tag = TagName.valueOf(tagName);
595	        AttributeKey srcset = AttributeKey.valueOf("srcset");
596	        AttributeKey src = AttributeKey.valueOf("src");
597	
598	        Set<Protocol> allowed = protocolsFor(tag, srcset);
599	        if (allowed == null) allowed = protocolsFor(tag, src);
600	        if (allowed == null && !tag.equals(AllTag)) {
601	            allowed = protocolsFor(AllTag, srcset);
602	            if (allowed == null) allowed = protocolsFor(AllTag, src);
603	        }
604	        return allowed == null ? Collections.emptySet() : allowed;
605	    }
606	
607	    private Set<Protocol> protocolsFor(TagName tag, AttributeKey key) {
608	        Map<AttributeKey, Set<Protocol>> byAttribute = protocols.get(tag);
609	        return byAttribute == null ? null : byAttribute.get(key);
610	    }
611	
612	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
613	        for (Protocol protocol : protocols) {
614	            String prot = protocol.toString();
615	
616	            if (prot.equals("#")) { // allows anchor links
617	                if (isValidAnchor(value)) {
618	                    return true;
619	                } else {
620	                    continue;
621	                }
622	            }
623	
624	            String lc = lowerCase(value);
625	            if (lc.startsWith(prot)
626	                && lc.length() > prot.length()
627	                && lc.charAt(prot.length()) == ':') {
628	                return true;
629	            }
630	        }
631	        return false;
632	    }
633	
634	    /**
635	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
636	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
637	     attribute.
638	     */
639	    boolean shouldAbsUrl(String tagName, String attrKey) {
640	        if (preserveRelativeLinks) return false;
641	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
642	    }
643	
644	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
645	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
646	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
647	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
648	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
649	        }
650	
651	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
652	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
653	
654	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
655	    }
656	
657	    private static boolean isValidAnchor(String value) {
658	        return value.startsWith("#") && !value.matches(".*\\s.*");
659	    }
660	
661	    /**
662	     Gets the Attributes that should be enforced for a given tag
663	     * @param tagName the tag
664	     * @return the attributes that will be enforced; empty if none are set for the given tag
665	     */
666	    public Attributes getEnforcedAttributes(String tagName) {
667	        Attributes attrs = new Attributes();
668	        TagName tag = TagName.valueOf(tagName);
669	        if (enforcedAttributes.containsKey(tag)) {
670	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
671	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
672	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
673	            }
674	        }
675	        return attrs;
676	    }
677	    
678	    // named types for config. All just hold strings, but here for my sanity.
679	
680	    static class TagName extends TypedValue {
681	        TagName(String value) {
682	            super(value);
683	        }
684	
685	        static TagName valueOf(String value) {
686	            return new TagName(Normalizer.lowerCase(value));
687	        }
688	    }
689	
690	    static class AttributeKey extends TypedValue {
691	        AttributeKey(String value) {
692	            super(value);
693	        }
694	
695	        static AttributeKey valueOf(String value) {
696	            return new AttributeKey(Normalizer.lowerCase(value));
697	        }
698	    }
699	
700	    static class AttributeValue extends TypedValue {
701	        AttributeValue(String value) {
702	            super(value);
703	        }
704	
705	        static AttributeValue valueOf(String value) {
706	            return new AttributeValue(value);
707	        }
708	    }
709	
710	    static class Protocol extends TypedValue {
711	        Protocol(String value) {
712	            super(value);
713	        }
714	
715	        static Protocol valueOf(String value) {
716	            return new Protocol(value);
717	        }
718	    }
719	
720	    abstract static class TypedValue {
721	        private final String value;
722	
723	        TypedValue(String value) {
724	            Validate.notNull(value);
725	            this.value = value;
726	        }
727	
728	        @Override
729	        public int hashCode() {
730	            return value.hashCode();
731	        }
732	
733	        @Override
734	        public boolean equals(Object obj) {
735	            if (this == obj) return true;
736	            if (obj == null || getClass() != obj.getClass()) return false;
737	            TypedValue other = (TypedValue) obj;
738	            return Objects.equals(value, other.value);
739	        }
740	
741	        @Override
742	        public String toString() {
743	            return value;
744	        }
745	    }
746	}
