175	        String noDesc = "<img srcset='\"http://example.com/a,b.jpg\", http://example.com/c.jpg 2x'>";
176	        assertEquals("<img srcset=\"http://example.com/a,b.jpg, http://example.com/c.jpg 2x\">",
177	            Jsoup.clean(noDesc, safelist()));
178	
179	        // inner commas/parentheses are literal for quoted relative addresses too
180	        String relative = "<img srcset='\"/a,b.jpg\" 1x, /c.jpg 2x'>";
181	        assertEquals("<img srcset=\"http://example.com/a,b.jpg 1x, http://example.com/c.jpg 2x\">",
182	            Jsoup.clean(relative, "http://example.com/path/", safelist()));
183	    }
