import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.*;

public class Scratch {
    static Safelist sl() {
        return Safelist.relaxed()
            .addTags("picture", "source")
            .addAttributes("img", "srcset")
            .addAttributes("source", "srcset", "media", "type");
    }
    static void t(String name, String html, Safelist sl) {
        String c = Jsoup.clean(html, "http://example.com/", sl);
        System.out.println("== " + name + " ==\n  " + c);
        System.out.println("  stable: " + c.equals(Jsoup.clean(c, "http://example.com/", sl)));
    }
    public static void main(String[] a) {
        t("basic picture",
          "<picture><source media=\"(min-width: 800px)\" srcset=\"/large.jpg 800w, javascript:x 1x\"><img src=\"/fallback.jpg\" srcset=\"/fb.jpg 1x\" alt=\"x\"></picture>", sl());
        t("nested picture",
          "<picture><source srcset=\"/a.jpg 1x,http://bad 2x\"><picture><source type=\"image/webp\" srcset=\"/b.webp\"></picture><img src=\"/f.jpg\" srcset=\"/f2.jpg 2x\"></picture>", sl());
        t("unterminated quote",
          "<picture><source srcset='\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x' media=\"(x)\"><img src=\"/f.jpg\"></picture>", sl());
        t("all invalid",
          "<picture><source media=\"(m)\" type=\"image/webp\" srcset=\"javascript:x 1x\"><img src=\"/f.jpg\"></picture>", sl());
        t("empty srcset",
          "<picture><source media=\"(m)\" srcset=\"\"><img src=\"/f.jpg\"></picture>", sl());
        // source tag not allowed
        t("no source tag",
          "<picture><source srcset=\"/a.jpg 1x\" media=\"(m)\"><img src=\"/f.jpg\"></picture>",
          Safelist.relaxed().addTags("picture").addAttributes("img","srcset"));
        // source allowed, srcset attr not
        t("no srcset attr",
          "<picture><source media=\"(m)\" srcset=\"/a.jpg 1x\"><img src=\"/f.jpg\"></picture>",
          Safelist.relaxed().addTags("picture","source").addAttributes("source","media","type").addAttributes("img","srcset"));
        // img/srcset consistency check: same value on source vs img
        String v = "http://example.com/a,b.jpg 1x, http://example.com/c d.jpg 2x, , http://x/y.jpg 300w";
        String h1 = "<img srcset=\""+v+"\">";
        String h2 = "<source srcset=\""+v+"\">";
        String c1 = Jsoup.clean(h1, "http://example.com/", sl());
        String c2 = Jsoup.clean(h2, "http://example.com/", sl());
        System.out.println("== parity ==\n  img: "+c1+"\n  src: "+c2);
    }
}
